    EAIActionReturn ret;
    C3DVector lineOfSightPos;
    if (!IsStillRunnable()) {
        Terminate();
        return;
    }
    TimingCritical = true;
    if (CircleMarkers.size() > 0) {
        if (RouteDirection == WASP_DIRECTION_CLOCKWISE)
            ret = GotoNextCirclePoint(AI_MOVEMENT_HOVER_MEDIUM);
        else
            ret = GotoPreviousCirclePoint(AI_MOVEMENT_HOVER_MEDIUM);
